import shutil, openpyxl
from copy import copy
from openpyxl.utils import get_column_letter
from datetime import datetime, date

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
src = openpyxl.load_workbook(INIT)

data_vals = vals["DATA"]
data_src = src["DATA"]
ws = wb["combined"] if "combined" in wb.sheetnames else wb.create_sheet("combined")

for mr in list(ws.merged_cells.ranges):
    if mr.min_row <= 8 and mr.max_row >= 1 and mr.min_col <= 18 and mr.max_col >= 1:
        ws.unmerge_cells(str(mr))

for r in range(1, 9):
    for c in range(1, 19):
        ws.cell(row=r, column=c).value = None

ref_col = 8
for c in range(1, 19):
    v = data_vals.cell(row=1, column=c).value
    if isinstance(v, str) and v.strip().lower() == "combokey":
        ref_col = c
        break

groups = {}
order = []
for r in range(2, data_vals.max_row + 1):
    key = data_vals.cell(row=r, column=ref_col).value
    if key is None:
        continue
    if isinstance(key, str):
        key = key.strip()
        if key == "":
            continue
    if key not in groups:
        groups[key] = []
        order.append(key)
    groups[key].append(r)

def clean_value(v):
    if v is None:
        return None
    if isinstance(v, str):
        v = v.strip()
        return v if v != "" else None
    return v

def maybe_date(v):
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y %H:%M:%S", "%m/%d/%Y"):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
    return v

def first_nonempty(rows, col):
    for r in rows:
        v = clean_value(data_vals.cell(row=r, column=col).value)
        if v is not None:
            return v
    return None

def sum_numeric(rows, col):
    total = 0.0
    found = False
    for r in rows:
        v = data_vals.cell(row=r, column=col).value
        if v is None or isinstance(v, bool):
            continue
        if isinstance(v, (int, float)):
            total += float(v)
            found = True
        elif isinstance(v, str):
            s = v.strip().replace(",", "")
            if s == "":
                continue
            try:
                total += float(s)
                found = True
            except ValueError:
                pass
    if not found:
        return None
    total = round(total, 2)
    if total == 0:
        return None
    if total == int(total):
        return int(total)
    return total

def copy_style(src_cell, dst_cell):
    dst_cell.font = copy(src_cell.font)
    dst_cell.border = copy(src_cell.border)
    dst_cell.fill = copy(src_cell.fill)
    dst_cell.number_format = src_cell.number_format
    dst_cell.protection = copy(src_cell.protection)
    dst_cell.alignment = copy(src_cell.alignment)

for c in range(1, 19):
    letter = get_column_letter(c)
    col_dim = data_src.column_dimensions.get(letter)
    if col_dim is not None and col_dim.width is not None:
        ws.column_dimensions[letter].width = col_dim.width

row_dim = data_src.row_dimensions.get(1)
if row_dim is not None and row_dim.height is not None:
    ws.row_dimensions[1].height = row_dim.height

for c in range(1, 19):
    v = clean_value(data_vals.cell(row=1, column=c).value)
    if c >= 9:
        v = maybe_date(v)
    cell = ws.cell(row=1, column=c)
    cell.value = v
    copy_style(data_src.cell(row=1, column=c), cell)
    if c >= 9 and isinstance(v, (datetime, date)):
        cell.number_format = "yyyy-mm-dd hh:mm:ss" if isinstance(v, datetime) else "yyyy-mm-dd"

max_out_rows = 7
for i, key in enumerate(order[:max_out_rows]):
    out_r = i + 2
    rows = groups[key]
    style_row = rows[0]
    for r in rows:
        has_value = False
        for c in range(1, 19):
            if clean_value(data_vals.cell(row=r, column=c).value) is not None:
                has_value = True
                break
        if has_value:
            style_row = r
            break
    row_dim = data_src.row_dimensions.get(style_row)
    if row_dim is not None and row_dim.height is not None:
        ws.row_dimensions[out_r].height = row_dim.height
    for c in range(1, 19):
        if c <= 8:
            v = first_nonempty(rows, c)
        else:
            v = sum_numeric(rows, c)
        cell = ws.cell(row=out_r, column=c)
        cell.value = v
        copy_style(data_src.cell(row=style_row, column=c), cell)
        if c >= 9:
            cell.number_format = "0.00;-0.00;;@"

wb.save(OUT)

print("groups:", len(order), "written:", min(len(order), max_out_rows))
for i, key in enumerate(order[:max_out_rows]):
    out_r = i + 2
    print(out_r, key, [ws.cell(row=out_r, column=c).value for c in range(9, 19)])
